					return false;

				if (!_lines.MoveNext())
				{
					_ended = true;

					return false;
				}

				_line = _lines.Current + "\n";
				_at    = 0;

				return true;
			}

			protected override void Dispose(bool disposing)
			{
				if (disposing)
					_lines.Dispose();

				base.Dispose(disposing);
			}
		}

