			internal void RemoveRange(int index, int count)
			{
				if (count == 0)
					return;

				var after = Count - index - count;

				if (after > 0)
					global::System.Array.Copy(_items, index + count, _items, index, after);

				Count -= count;
			}

			internal void Clear()
			{
				Count = 0;
			}
		}

		private readonly struct ParserEntry
